<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import PageHeader from '@/components/PageHeader.vue'
import DatePicker from '@/components/DatePicker.vue'
import { memberApi } from '@/api'
import { useAppStore } from '@/stores/app'
import { useAuthStore } from '@/stores/auth'
import { notifyFamilyChanged } from '@/utils/data-changed'
import { genderLabel, memberInput, requireTreeId } from '@/utils/backend'
import type { Gender, Member } from '@/types'
const app=useAppStore(),auth=useAuthStore(),rows=ref<Member[]>([]),loading=ref(false),dialog=ref(false),query=reactive({keyword:'',gender:''}),form=reactive<any>({name:'',gender:'MALE',birthDate:'',birthPlace:'',occupation:''})
const filtered=computed(()=>rows.value.filter(m=>(!query.keyword||[m.name,m.birthPlace,m.occupation].some(v=>v?.includes(query.keyword)))&&(!query.gender||m.gender===query.gender)))
async function load(){loading.value=true;try{rows.value=await memberApi.list(requireTreeId(app.activeTreeId))}catch(e){ElMessage.error((e as Error).message)}finally{loading.value=false}}
async function save(){if(!form.name)return ElMessage.warning('请填写姓名');await memberApi.create(requireTreeId(app.activeTreeId),memberInput(form));notifyFamilyChanged(app.activeTreeId);ElMessage.success('成员已添加');dialog.value=false;load()}
async function remove(row:Member){await ElMessageBox.confirm(`确定删除成员“${row.name}”吗？有后代时后端会拒绝删除。`,'删除成员',{type:'warning'});await memberApi.remove(requireTreeId(app.activeTreeId),row.id);notifyFamilyChanged(app.activeTreeId);load()}
onMounted(load)
</script>
<template><PageHeader title="成员管理" :description="`当前家谱 ID：${app.activeTreeId||'未选择'}`"><el-button @click="$router.push('/trees')">选择家谱</el-button><el-button v-if="auth.user?.memberId&&Number(auth.user.memberTreeId)===Number(app.activeTreeId)" type="primary" plain @click="$router.push(`/members/${auth.user.memberId}`)">我的资料</el-button><el-button v-permission="'member:edit'" type="primary" @click="dialog=true">新增成员</el-button></PageHeader><section class="panel"><div class="filters"><el-input v-model="query.keyword" clearable placeholder="姓名、籍贯、职业" style="width:240px"/><el-select v-model="query.gender" clearable placeholder="性别" style="width:120px"><el-option v-for="(label,value) in genderLabel" :key="value" :label="label" :value="value"/></el-select><el-button @click="load">刷新</el-button></div><el-table v-loading="loading" :data="filtered" stripe><el-table-column prop="name" label="姓名"><template #default="{row}"><el-link type="primary" @click="$router.push(`/members/${row.id}`)">{{row.name}}<el-tag v-if="row.id===auth.user?.memberId" size="small" style="margin-left:6px">本人</el-tag></el-link></template></el-table-column><el-table-column label="性别" width="90"><template #default="{row}">{{genderLabel[row.gender as Gender]}}</template></el-table-column><el-table-column prop="birthDate" label="出生日期"/><el-table-column prop="birthPlace" label="出生地"/><el-table-column prop="occupation" label="职业"/><el-table-column label="操作" width="180"><template #default="{row}"><el-button link type="primary" @click="$router.push(`/members/${row.id}`)">详情</el-button><el-button v-permission="'relation:edit'" link @click="$router.push(`/relations?memberId=${row.id}`)">关系</el-button><el-button v-permission="'member:edit'" link type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table><el-empty v-if="!loading&&!filtered.length" description="暂无成员"/></section><el-dialog v-model="dialog" title="新增成员" width="min(600px,94vw)"><el-form label-position="top"><div class="form-grid"><el-form-item label="姓名" required><el-input v-model="form.name"/></el-form-item><el-form-item label="性别"><el-select v-model="form.gender" style="width:100%"><el-option v-for="(label,value) in genderLabel" :key="value" :label="label" :value="value"/></el-select></el-form-item><el-form-item label="出生日期"><DatePicker v-model="form.birthDate" placeholder="请选择出生日期"/></el-form-item><el-form-item label="出生地"><el-input v-model="form.birthPlace"/></el-form-item><el-form-item label="职业"><el-input v-model="form.occupation"/></el-form-item></div></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></template>
